local _, ns = ...
if ns.LOCALE ~= "itIT" then return end
local L = ns.L

-- Options/HelpPanes.lua: the FAQ and Support pages, beside Locales/itIT.lua.
L["FAQ_CAPTION"] = "Domande frequenti, e dove sono finite le cose."
L["FAQ_SEARCH"] = "Cerca domande"
L["FAQ_NONE"] = "Nessuna domanda corrisponde."
L["FAQ_NOT_BOUND"] = "non assegnato"
L["FAQ_LFG_Q"] = "Dov'è il mio pulsante LFG (ricerca gruppo)?"
L["FAQ_LFG_A"] = "La 1.x non lo aveva, quindi non è nel micromenu. Clicca l'occhio sulla minimappa, usa le schede laterali della scheda Chi della finestra social, oppure premi il tasto della ricerca gruppo (%s). Per riavere il pulsante, togli la spunta a \"%s\" sotto \"%s\"."
L["FAQ_LEGACY_Q"] = "Dov'è il mio pulsante Eredità?"
L["FAQ_LEGACY_A"] = "La 1.x non ne aveva, quindi non è nel micromenu. Clicca la sua icona sulla minimappa. Per riavere il pulsante, deseleziona \"%s\" in \"%s\". Qualsiasi pulsante del micromenu può stare sulla minimappa: selezionalo in \"%s\"."
L["FAQ_PROFESSIONS_Q"] = "Dov'è il mio pulsante delle professioni?"
L["FAQ_PROFESSIONS_A"] = "La 1.x non lo aveva, quindi non è nel micromenu. Apri le tue professioni dal libro degli incantesimi, oppure premi il tasto delle professioni (%s). Per riavere il pulsante, togli la spunta a \"%s\" sotto \"%s\"."
L["FAQ_COLLECTIONS_Q"] = "Dov'è il mio pulsante delle collezioni?"
L["FAQ_COLLECTIONS_A"] = "La 1.x non lo aveva, quindi non è nel micromenu. Apri cavalcature, mascotte, giocattoli e aspetti dalla scheda \"%s\" ai piedi del libro degli incantesimi, oppure premi il tasto delle collezioni (%s). Per riavere il pulsante, togli la spunta a \"%s\" sotto \"%s\"."
L["FAQ_QUICKJOIN_Q"] = "Dov'è la scheda %s?"
L["FAQ_QUICKJOIN_A"] = "Nella finestra sociale apri %s e poi %s. La scheda %s sotto l'elenco passa a quella lista e la scheda %s torna indietro."
L["FAQ_REAGENT_Q"] = "Dov'è la mia borsa dei reagenti?"
L["FAQ_REAGENT_A"] = "È la piccola borsa rotonda tra il portachiavi e la tua ultima borsa, visibile mentre il mouse è sopra le borse. Per tenerla sempre in vista scegli \"%s\", oppure \"%s\" per uno spazio come le altre borse."
L["FAQ_TENBUTTONS_Q"] = "Perché la mia barra principale mostra 10 pulsanti, o la dimensione sbagliata?"
L["FAQ_TENBUTTONS_A"] = "La fascia segue le impostazioni della barra delle azioni 1 in modalità modifica: \"%s\" e \"%s\". \"%s\" nella pagina \"%s\" dà i pulsanti più piccoli della 1.x."
L["FAQ_GRYPHONS_Q"] = "Come nascondo i grifoni?"
L["FAQ_GRYPHONS_A"] = "Nella pagina \"%s\", imposta \"%s\" o \"%s\" su \"%s\". In modalità modifica ogni grifone è un pezzo a sé, da spostare o nascondere."
L["FAQ_XPBAR_Q"] = "Posso nascondere la barra dell'esperienza o toglierla dalla fascia?"
L["FAQ_XPBAR_A"] = "Sì, in modalità modifica. Clicca sulla barra dell'esperienza o della reputazione: si può trascinare fuori dalla fascia, e il suo riquadro ha \"%s\"."
L["FAQ_SIZE_Q"] = "Perché le finestre sono più piccole di quelle del gioco? Posso ingrandirle?"
L["FAQ_SIZE_A"] = "Sono le dimensioni di Classic Era. Clicca il lucchetto nella barra del titolo di una finestra e trascina la maniglia nel suo angolo, oppure regolane la dimensione in modalità modifica in \"%s\". Le barre seguono \"%s\" e la dimensione nel riquadro di ogni barra in modalità modifica."
L["FAQ_SCALE_Q"] = "Perché la mia interfaccia è diventata più grande?"
L["FAQ_SCALE_A"] = "Classic Era disegna la sua interfaccia più grande di Forever. Scegliere il layout classico con la dimensione di Era imposta su di essa la scala dell'interfaccia del gioco, 90%% sulla maggior parte degli schermi. Cambiala quando vuoi in %s, nelle opzioni del gioco (\"%s\")."
L["FAQ_SCALEBACK_Q"] = "Come recupero la mia vecchia dimensione dell'interfaccia?"
L["FAQ_SCALEBACK_A"] = "Premi \"%s\" nella barra laterale con \"%s\" spuntata: la tua dimensione di prima torna con le opzioni. Oppure regolala in %s nelle opzioni del gioco; togli la spunta a \"%s\" per la dimensione automatica del gioco."
L["FAQ_SCALEBACK_PIECE_A"] = "Regolala in %s nelle opzioni del gioco; togli la spunta a \"%s\" per la dimensione automatica del gioco."
L["FAQ_GLOW_Q"] = "Come tolgo il bagliore rosso dai miei riquadri?"
L["FAQ_GLOW_A"] = "Nella pagina \"%s\": \"%s\" per il bagliore rosso quando qualcosa ti attacca, \"%s\" per la pulsazione del tuo riquadro mentre attacchi."
L["FAQ_TRACKER_Q"] = "Posso riavere il vecchio tracciamento delle missioni?"
L["FAQ_TRACKER_A"] = "Sì. Nella pagina \"%s\", \"%s\" sceglie il suo aspetto, tra cui il monitoraggio missioni di Classic Era."
L["FAQ_PLATES_Q"] = "Come ingrandisco le barre dei nomi?"
L["FAQ_PLATES_A"] = "La loro dimensione è quella del gioco, in \"%s\" nelle sue Opzioni. \"%s\" nella pagina \"%s\" cambia solo il nome."
L["FAQ_MOVE_Q"] = "Posso spostare le finestre?"
L["FAQ_MOVE_A"] = "Sì, fuori dal combattimento. Passa il mouse sulla barra del titolo di una finestra e clicca il suo lucchetto, poi trascinala dal titolo. Oppure posiziona le finestre in modalità modifica sotto \"%s\". Il pulsante rosso accanto al lucchetto riporta la finestra al suo posto predefinito."
L["FAQ_MOVERS_Q"] = "Perché il mio addon per spostare le finestre ne sposta alcune e altre no?"
L["FAQ_MOVERS_A"] = "La scheda del personaggio e le altre finestre del gioco sono quelle del gioco con l'aspetto della 1.x, quindi questi addon possono spostarle; \"%s\" nelle opzioni gliele lascia del tutto. Il nostro libro degli incantesimi e il registro delle missioni li facciamo noi, perché il gioco non ne ha di simili a quelli di Era, e questi addon spostano solo le finestre della loro lista. Le nostre si spostano con il lucchetto sulla barra del titolo o in modalità modifica."
L["FAQ_SETTING_Q"] = "Posso cambiare l'aspetto o il funzionamento di qualcosa?"
L["FAQ_SETTING_A"] = "Molto probabilmente. Quasi ogni parte si può disattivare o regolare: scrivi una parola nella casella \"%s\" in alto a sinistra di questa finestra. Se non lo trovi, chiedi su GitHub o CurseForge."
L["FAQ_FOREVER_Q"] = "Posso mantenere l'aspetto proprio di Forever per alcune parti?"
L["FAQ_FOREVER_A"] = "Sì. Ogni parte classica ha il suo interruttore in questa finestra; spegnila e torna quella di Forever. Alcune modifiche richiedono un ricaricamento, e una finestra te lo chiede."
L["FAQ_OTHER_ADDON_Q"] = "Potete far funzionare %s con un altro addon?"
L["FAQ_OTHER_ADDON_A"] = "Dicci quale su GitHub o CurseForge e ci daremo un'occhiata. Quando due addon modificano la stessa parte dello schermo, disattivare quella parte qui di solito fa funzionare entrambi."
L["FAQ_LFG_RETAIL_A"] = "La 1.x non lo aveva, quindi non è nel micromenu. Clicca l'occhio sulla minimappa, oppure premi il tasto della ricerca gruppo (%s). Per riavere il pulsante, togli la spunta a \"%s\" sotto \"%s\"."
L["FAQ_REAGENT_RETAIL_A"] = "Sta nel vecchio spazio del portachiavi, in fondo alle borse. Per uno spazio come le altre borse scegli \"%s\"."
L["FAQ_OWNLOOK_Q"] = "Posso mantenere l'aspetto proprio del gioco per alcune parti?"
L["FAQ_OWNLOOK_A"] = "Sì. Ogni parte classica ha il suo interruttore in questa finestra; spegnila e torna quella del gioco. Alcune modifiche richiedono un ricaricamento, e una finestra te lo chiede."
L["FAQ_RETAILBUTTONS_Q"] = "Dove sono i miei pulsanti %s, %s e %s?"
L["FAQ_RETAILBUTTONS_A"] = "La 1.x non li aveva, quindi non sono nel micromenu. Clicca le loro icone sulla minimappa, oppure premi il tasto di %s (%s) o di %s (%s). Per riavere un pulsante, togli la sua spunta sotto \"%s\"."
L["FAQ_SUITE_Q"] = "Che cos'è ClassicUI Forever?"
L["FAQ_SUITE_A"] = "La raccolta completa di addon da cui viene questa parte: tutto l'aspetto della 1.x, dalle barre e borse ai riquadri delle unità, alle mappe e alle finestre. Ne funziona uno alla volta, quindi per più di questa parte usa ClassicUI Forever completo e disattiva ciò che non ti serve."
L["FAQ_SUITE_PICKER_A"] = "La raccolta completa di addon per cui è nato questo selettore di colori: tutto l'aspetto della 1.x, dalle barre e borse ai riquadri delle unità, alle mappe e alle finestre, con questo selettore di colori incluso. Ne funziona uno alla volta, quindi per averli entrambi usa ClassicUI Forever completo."
L["FAQ_MICRO_KEY_A"] = "La 1.x non lo aveva, quindi non è nel micromenu. Premi il suo tasto (%s). Per riavere il pulsante, togli la spunta a \"%s\" sotto \"%s\"."
L["FAQ_MICRO_OFF_A"] = "La 1.x non lo aveva, quindi non è nel micromenu. Per riavere il pulsante, togli la spunta a \"%s\" sotto \"%s\"."
L["FAQ_RETAILBUTTONS_KEY_A"] = "La 1.x non li aveva, quindi non sono nel micromenu. Premi il tasto di %s (%s) o di %s (%s). Per riavere un pulsante, togli la sua spunta sotto \"%s\"."
L["SUPPORT_CAPTION"] = "Grazie per usare %s."
L["SUPPORT_FEEDBACK_HEAD"] = "Commenti"
L["SUPPORT_FEEDBACK"] = "Segnalazioni di bug, idee e ogni altro commento sono sempre benvenuti. Prima di scrivere, premi %s e incolla nella segnalazione quello che ti dà: le tue impostazioni, la versione del gioco e gli altri addon."
L["SUPPORT_POST"] = "Poi scegli dove pubblicarlo. I pulsanti copiano l'indirizzo da incollare nel browser."
L["SUPPORT_MORE_HEAD"] = "Potrebbe piacerti anche"
L["SUPPORT_MORE"] = "EasyFind, sempre da noi: una palette di comandi per il gioco. Scrivi quello che vuoi e fallo direttamente dai risultati: apri una finestra o un'impostazione, monta in sella, lancia un incantesimo o trova un luogo sulla mappa."
L["SUPPORT_MORE_BUTTON"] = "EasyFind su CurseForge"
L["SUPPORT_SUITE_BUTTON"] = "ClassicUI Forever su CurseForge"
L["SUPPORT_DONATE_HEAD"] = "Sostieni l'addon"
L["SUPPORT_DONATE"] = "%s è gratuito. Se vuoi sostenerlo, puoi farlo tramite Buy Me a Coffee."
L["SUPPORT_DONATE_BUTTON"] = "Buy Me a Coffee"

-- Era's interface size (Options/EraScale.lua).
L["ERASCALE_OFFER"] = "Classic Era mostra la sua interfaccia più grande di Forever come impostazione predefinita. Passare alla dimensione di Era, con le barre di dimensione classica? L'interfaccia si ricarica. L'impostazione %s del gioco cambia la dimensione quando vuoi."
L["ERASCALE_GIVEN_BACK"] = "Dimensione dell'interfaccia ripristinata. Sembra diversa da come te l'aspettavi? Clicca %s."
L["ERASCALE_HELP"] = "La dimensione dell'interfaccia è tornata a quella di prima del layout classico, o alla dimensione automatica del gioco. Se sembra ancora troppo grande o piccola, regolala in %s nelle opzioni del gioco: togli la spunta a \"%s\" per la dimensione automatica, o sposta il suo cursore."
L["ERASCALE_OPEN_SETTINGS"] = "Opzioni di gioco"
L["ERASCALE_SWITCH"] = "Usa la dimensione di Era"
L["ERASCALE_ASK"] = "Su questo schermo la tua interfaccia ha una dimensione diversa da quella di Classic Era. Passare alla dimensione di Era, con le barre di dimensione classica? L'impostazione %s del gioco la cambia quando vuoi."
L["ERASCALE_KEEP"] = "Tieni la mia dimensione"
